}
#minimap[data-compact="true"] #structural-preview-button span { display: block; white-space: nowrap; font-size: 9px; }
#minimap[data-compact="true"][data-compact-collapsed="true"] {
  max-height: calc(100dvh - 16px - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px));
}
@media (orientation: landscape) and (min-width: 520px) {
  #minimap.minimap-touch[data-compact="true"] {
    right: calc(164px + env(safe-area-inset-right, 0px));
    max-width: calc(100vw - 328px - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px));
  }
  #minimap.minimap-touch[data-compact="true"][data-compact-collapsed="true"] {
    left: calc(164px + env(safe-area-inset-left, 0px));
    right: calc(164px + env(safe-area-inset-right, 0px));
    width: auto;
    max-width: 320px;
    margin-inline: auto;
  }
}

/* Place details replace only the map's content, within its existing safe box. */
#minimap #teleport-heading,
#minimap #place-list h2,
#minimap #bridge-facilities h2 { color: #ffe4a1; font-size: 16px; margin: 14px 0 8px; }
#minimap #place-list,
#minimap #bridge-facilities { display: flex; flex-wrap: wrap; gap: 6px; }
#minimap #place-list h2,
#minimap #bridge-facilities h2 { flex-basis: 100%; }
#minimap #place-search {
  flex-basis: 100%; width: 100%; min-width: 0; min-height: 44px;
  box-sizing: border-box; border: 1px solid #9f804a; border-radius: 6px;
  background: #211c17; color: #ffe4a1; padding: 8px 12px; font: inherit;
}
#minimap #place-search::placeholder { color: #d3c7b0; }
#minimap #place-search-count { flex-basis: 100%; margin: 2px 0; color: #d3c7b0; font-size: 14px; }
#minimap #place-directory,
#minimap #bridge-facility-directory {
  display: flex; flex-wrap: wrap; gap: 6px; width: 100%;
  max-height: min(240px, 36dvh); overflow-y: auto; overscroll-behavior: contain;
  touch-action: pan-y;
}
/* Keep the directory scroll offset when translated labels reflow. */
#minimap #place-directory { overflow-anchor: none; }
#minimap #place-directory button[hidden],
#minimap #bridge-facility-directory button[hidden] { display: none !important; }

#minimap #place-list button,
#minimap #bridge-facility-directory button,
#minimap #place-resume,
#minimap #place-header button,
#minimap #place-info button {
  min-width: 44px;
  min-height: 44px;
  padding: 8px 12px;
  border: 1px solid #9f804a;
  border-radius: 6px;
  background: #382d20;
  color: #ffe4a1;
  font-size: 14px;
  line-height: 1.45;
  overflow-wrap: anywhere;
  cursor: pointer;
  touch-action: manipulation;
}
#minimap #place-resume { margin-top: 10px; }
#minimap[data-detail="true"] {
  display: flex !important;
  flex-direction: column;
  height: min(640px, 96dvh);
  overflow: hidden !important;
}
#minimap.minimap-touch[data-detail="true"] {
  height: min(640px, calc(100dvh - 200px - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px)));
}
@media (orientation: landscape) and (min-width: 520px) {
  #minimap.minimap-touch[data-detail="true"] {
    height: min(640px, calc(100dvh - 16px - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px)));
  }
}
#minimap[data-detail="true"] #minimap-presentation,
#minimap[data-detail="true"] #structural-preview-button { flex-shrink: 0; }
#minimap #place-header { display: flex; gap: 8px; flex-shrink: 0; margin-bottom: 8px; }
#minimap #place-header button { flex: 1; margin: 0 !important; }
#minimap #place-info {
  min-width: 0;
  min-height: 0;
  overflow-y: auto;
  overflow-wrap: anywhere;
  overscroll-behavior: contain;
  touch-action: pan-y;
  color: #f1e8d5;
  font-size: 16px;
  line-height: 1.65;
  padding: 0 8px 12px 0;
}
#minimap #place-info h2 { margin: 2px 0 0; font-size: 24px; color: #ffe4a1; }
#minimap #place-info h3 { margin: 20px 0 8px; font-size: 17px; color: #ffe4a1; }
#minimap #place-info p { margin: 8px 0; }
#minimap #place-info .place-tag { color: #d9bc7d; font-size: 14px; }
#minimap #place-info .place-note { color: #d3c7b0; font-size: 14px; }
#minimap #place-info ul { padding-left: 22px; }
#minimap #place-info li { margin-bottom: 10px; }
#minimap #place-info a { display: inline-block; min-height: 44px; padding-block: 6px; box-sizing: border-box; color: #ffe4a1; }
#minimap #place-info a:focus-visible,
#minimap #place-info h2:focus-visible { outline: 3px solid #ffe4a1; outline-offset: -3px; }
#minimap #place-announcement { position: absolute; width: 1px; height: 1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
@media (max-height: 340px) {
  #minimap[data-detail="true"] { padding: 8px !important; }
  #minimap[data-detail="true"] #minimap-presentation { margin-bottom: 4px; }
  #minimap[data-detail="true"] #structural-preview-button { margin-bottom: 4px; min-height: 44px; }
}

/* Keep the persistent location label clear of closed and compact maps. */
body:has(#minimap.minimap-touch) #location-panel {
  top: calc(20px + env(safe-area-inset-top, 0px)) !important;
  left: calc(20px + env(safe-area-inset-left, 0px)) !important;
  padding: 8px 12px !important;
  font-size: 14px !important;
  overflow-wrap: anywhere;
}
body:not(.map-open):has(#minimap-preview) #location-panel {
  /* 20px left + 12px gap + 118px preview + 16px right. */
  max-width: calc(100vw - 166px - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px));
}
body:has(#minimap[data-compact="true"]) #location-panel {
  /* Desktop card: 240px wide, with its 8px right margin. */
  max-width: calc(100vw - 280px - env(safe-area-inset-right, 0px));
  overflow-wrap: anywhere;
}
body:has(#minimap.minimap-touch[data-compact="true"]) #location-panel {
  max-width: calc(100vw - 260px - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px));
}
@media (orientation: landscape) and (min-width: 520px) {
  body:has(#minimap.minimap-touch[data-compact="true"]) #location-panel {
    /* The card reserves a 164px right control lane and shrinks if needed. */
    max-width: max(132px, calc(100vw - 416px - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px)));
  }
  body:has(#minimap.minimap-touch[data-compact="true"][data-compact-collapsed="true"]) #location-panel {
    /* Short strip is centered, capped at 320px, between the two 164px lanes. */
    max-width: max(132px, calc((100vw - 384px - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px)) / 2));
  }
}
@media (max-width: 360px) {
  body:has(#minimap[data-compact="true"]) #location-panel {
    /* 8px top + maximum 236px card + 12px gap; keep long labels readable. */
    top: calc(256px + env(safe-area-inset-top, 0px)) !important;
    max-width: calc(100vw - 40px - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px)) !important;
  }
  body:has(#minimap[data-compact="true"][data-compact-collapsed="true"]) #location-panel {
    /* Without the canvas the compact strip is at most 92px high. */
    top: calc(112px + env(safe-area-inset-top, 0px)) !important;
  }
}

/* R79 readable project entry; links retain the existing anchor input exclusion. */
.welcome-content { max-height: calc(100dvh - 40px); overflow-y: auto; }
.welcome-content .project-summary { font-size: 14px; line-height: 1.55; margin: 10px 0; }
.project-discovery { display: flex; flex-wrap: wrap; justify-content: center; gap: 12px; margin: 14px 0; }
.project-discovery a { color: #f1d58d; text-decoration: underline; padding: 5px; }
.project-discovery a:focus-visible { outline: 2px solid #fff; outline-offset: 3px; }
.no-script-project { position: fixed; inset: 0; z-index: 10001; overflow: auto; padding: 2rem; background: #171b23; color: #fff; }
.no-script-project a { color: #f1d58d; }

/* Bilingual presentation controls. These never own world or map input. */
.language-control { display: flex; align-items: center; justify-content: center; gap: 8px; max-width: 100%; color: #fff2ce; font: 13px/1.4 system-ui, sans-serif; }
.language-control select { min-height: 44px; min-width: 112px; max-width: 100%; padding: 7px 10px; color: #fff2ce; background: #241f18; border: 1px solid #bfa36c; border-radius: 7px; font: inherit; }
.language-control select:focus-visible { outline: 3px solid #fff2ce; outline-offset: 2px; }
#tour-language-control { position: fixed; left: 50%; bottom: calc(64px + env(safe-area-inset-bottom, 0px)); transform: translateX(-50%); z-index: 9200; width: max-content; max-width: calc(100vw - 24px); padding: 2px 8px; border-radius: 8px; background: #161512ed; }
#settings-language-control { justify-content: space-between; margin: 14px 0; padding: 8px 0; border-top: 1px solid #655235; }
body.settings-open #tour-language-control, body.map-open #tour-language-control { visibility: hidden; }
@media (max-width: 600px) and (orientation: portrait) { #tour-language-control { bottom: calc(300px + env(safe-area-inset-bottom, 0px)); } }

/* Supplemental descriptions share search and card state, never add travel targets. */
#minimap #supplemental-place-list { display:flex;flex-wrap:wrap;gap:6px; }
#minimap #supplemental-place-list h2 { flex-basis:100%;color:#ffe4a1;font-size:16px;margin:14px 0 8px; }
#minimap #supplemental-place-directory { display:flex;flex-wrap:wrap;gap:6px;width:100%;max-height:min(240px,36dvh);overflow-y:auto;overscroll-behavior:contain;touch-action:pan-y; }
#minimap #supplemental-place-directory button { min-width:44px;min-height:44px;padding:8px 12px;border:1px solid #9f804a;border-radius:6px;background:#382d20;color:#ffe4a1;font-size:14px;line-height:1.45;overflow-wrap:anywhere;cursor:pointer;touch-action:manipulation; }
#minimap #supplemental-place-directory button[hidden] { display:none!important; }

#minimap-presentation { flex-wrap:wrap; }
#map-language-control { flex-basis:100%;width:100%; }
#minimap[data-compact="true"] #map-language-control { grid-area:4 / 1 / auto / -1; }
@media (max-width: 768px) and (orientation: portrait) {
  html[lang="en"] body::before {
    content: "For a better experience, rotate your device";
    white-space: normal; width: max-content; max-width: calc(100vw - 24px); text-align: center;
  }
}

style.css.after:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  width: 100vw;
  height: 100vh;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: #000;
  color: #fff;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* 加载界面 */
#loading-screen {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 9999;
  transition: opacity 0.5s ease;
}

.loading-content {
  text-align: center;
  max-width: 500px;
  padding: 20px;
}

.loading-content h1 {
  font-size: 32px;
  margin-bottom: 40px;
  color: #DAA520;
  text-shadow: 0 0 20px rgba(218, 165, 32, 0.5);
  letter-spacing: 4px;
}

.progress-container {
  width: 100%;
  height: 8px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 4px;
  overflow: hidden;
  margin-bottom: 20px;
}

.progress-bar {
  width: 0%;
  height: 100%;
  background: linear-gradient(90deg, #DAA520, #FFD700);
  border-radius: 4px;
  transition: width 0.3s ease;
  box-shadow: 0 0 10px rgba(218, 165, 32, 0.8);
}

#progress-text {
  font-size: 16px;
  color: rgba(255, 255, 255, 0.8);
}

/* 欢迎覆盖层 */
.welcome-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.8);
  display: none;
  justify-content: center;
  align-items: center;
  z-index: 9000;
}

.welcome-content {
  text-align: center;
  padding: 40px;
  background: rgba(26, 26, 46, 0.95);
  border-radius: 16px;
  border: 2px solid rgba(218, 165, 32, 0.3);
  max-width: 500px;
}

.welcome-content h2 {
  font-size: 28px;
  margin-bottom: 20px;
  color: #DAA520;
}

.welcome-content p {
  font-size: 18px;
  margin-bottom: 30px;
  color: rgba(255, 255, 255, 0.9);
}

.controls-hint {
  display: flex;
  flex-direction: column;
  gap: 15px;
  margin-top: 30px;
}

.hint-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 20px;
  background: rgba(255, 255, 255, 0.05);
  border-radius: 8px;
}

.hint-item strong {
  color: #DAA520;
  font-size: 16px;
}

.hint-item span {
  color: rgba(255, 255, 255, 0.7);
  font-size: 14px;
}

/* 场景容器 */
#scene-container {
  width: 100%;
  height: 100%;
}

#scene-canvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
}

/* 位置信息面板 */
#location-panel {
  pointer-events: none;
  user-select: none;
}

#help-panel {
  position: fixed;
  top: 96px;
  left: 20px;
  z-index: 1000;
  max-width: min(320px, calc(100vw - 40px));
  color: #f1e5cb;
  background: rgba(15, 14, 12, .8);
  border-radius: 6px;
  font: 13px/1.5 Arial, sans-serif;
  user-select: none;
}
#help-panel > button { min-height: 40px; padding: 6px 12px; color: inherit; background: transparent; border: 1px solid #a4916c; border-radius: 6px; cursor: pointer; }
#help-panel-body { padding: 4px 12px 10px; max-height: calc(100dvh - 190px); overflow-y: auto; }
#help-panel-body[hidden] { display: none; }
#help-panel-body p { margin: 7px 0; }
body.map-open #help-panel { display: none; }
#location-panel .model-status { display: block; margin-top: 3px; font-size: 11px; color: #ded0af; }

/* 画质按钮 */
#quality-button {
  transition: all 0.3s ease;
}

#quality-button:hover {
  background: rgba(255, 255, 255, 0.3);
  transform: scale(1.05);
}

#quality-button:active {
  transform: scale(0.95);
}

/* 虚拟摇杆样式 */
.joystick-base {
  touch-action: none;
}

.joystick-stick {
  touch-action: none;
}

/* 视角锁定按钮 */
.look-lock-button {
  transition: all 0.3s ease;
  touch-action: manipulation;
}

.look-lock-button:active {
  transform: scale(0.95);
  background: rgba(255, 255, 255, 0.5);
}

/* 移动端优化 */
@media (max-width: 768px) {
  .loading-content h1 {
    font-size: 24px;
    margin-bottom: 30px;
  }

  #progress-text {
    font-size: 14px;
  }

  #location-panel {
    font-size: 14px;
    padding: 10px 15px;
  }

  #help-panel {
    font-size: 12px;
    line-height: 1.5;
    left: 10px;
    top: 90px;
  }

  #quality-button {
    padding: 8px 16px;
    font-size: 12px;
  }

  .welcome-content {
    max-width: 90%;
    padding: 30px 20px;
  }

  .welcome-content h2 {
    font-size: 24px;
  }

  .welcome-content p {
    font-size: 16px;
  }
}

/* 横屏提示（移动端） */
@media (max-width: 768px) and (orientation: portrait) {
  body::before {
    content: "为了更好的体验，请横屏浏览";
    position: fixed;
    bottom: 190px;
    left: 50%;
    transform: translateX(-50%);
    white-space: nowrap;
    pointer-events: none;
    padding: 10px 20px;
    background: rgba(218, 165, 32, 0.9);
    color: #000;
    border-radius: 8px;
    font-size: 14px;
    z-index: 10000;
    animation: fadeInOut 3s ease-in-out infinite;
  }
}

/* 打开全图时隐藏横屏提示，避免遮挡地图 */
body.map-open::before {
  display: none !important;
}

@keyframes fadeInOut {
  0%, 100% {
    opacity: 0.5;
  }
  50% {
    opacity: 1;
  }
}

/* 禁用文本选择 */
body, button, div {
  -webkit-user-select: none;
  -moz-user-select: none;
  -ms-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

/* 滚动条隐藏 */
::-webkit-scrollbar {
  display: none;
}

/* 高对比度模式适配 */
@media (prefers-contrast: high) {
  #location-panel,
  #help-panel {
    background: rgba(0, 0, 0, 0.9);
    border: 2px solid #fff;
  }

  #quality-button,
  .look-lock-button {
    border: 3px solid #fff;
  }
}

/* 减少动画模式 */
@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
  }
}

/* Requested two-line author credit retains the touch-accessible settings entry. */
#structural-preview-button {
  position: fixed;
  left: 50%;
  bottom: max(8px, env(safe-area-inset-bottom, 0px));
  transform: translateX(-50%);
  width: max-content;
  max-width: calc(100% - 32px);
  min-height: 44px;
  padding: 6px 12px;
  border: 1px solid #bfa36c;
  border-radius: 8px;
  background: rgba(22, 21, 18, 0.9);
  color: #eee2c5;
  font: 12px/1.4 sans-serif;
  text-align: center;
  cursor: pointer;
  z-index: 9100;
  touch-action: manipulation;
}
#structural-preview-button strong,
#structural-preview-button span {
  display: block;
}

#settings-overlay {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100vh;
  height: 100dvh;
  padding: max(12px, env(safe-area-inset-top, 0px)) max(12px, env(safe-area-inset-right, 0px)) max(12px, env(safe-area-inset-bottom, 0px)) max(12px, env(safe-area-inset-left, 0px));
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.7);
  backdrop-filter: blur(8px);
}
#settings-panel {
  display: flex;
  flex-direction: column;
  width: 520px;
  max-width: 100%;
  max-height: 100%;
  min-height: 0;
  overflow: hidden;
  color: #fff;
  background: rgba(30, 30, 30, 0.98);
  border: 2px solid rgba(200, 150, 80, 0.8);
  border-radius: 12px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.6);
  font: 15px/1.55 sans-serif;
}
.settings-header {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 20px;
  border-bottom: 1px solid #655235;
}
#settings-title {
  margin: 0;
  color: #e8d4a0;
  font-size: 23px;
}
#settings-content {
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
  scrollbar-width: thin;
  scrollbar-color: #c6a265 #302c25;
  padding: 16px 20px;
  touch-action: pan-y;
  -webkit-user-select: text;
  user-select: text;
}
#settings-content::-webkit-scrollbar {
  display: block;
  width: 8px;
}
#settings-content::-webkit-scrollbar-thumb {
  background: #c6a265;
  border-radius: 4px;
}
#settings-content::-webkit-scrollbar-track {
  background: #302c25;
}
#settings-content p,
#settings-content li {
  -webkit-user-select: text;
  user-select: text;
}
.settings-notice {
  padding: 10px 12px;
  margin-bottom: 16px;
  color: #eadaba;
  background: #393124;
  border-radius: 6px;
}
.settings-control { margin-bottom: 16px; }
.settings-control label { display: block; margin-bottom: 6px; }
#settings-panel button {
  min-height: 44px;
  padding: 10px 14px;
  border: 1px solid #b9a279;
  border-radius: 6px;
  background: #393a3c;
  color: #fff;
  font: inherit;
  cursor: pointer;
  touch-action: manipulation;
}
.settings-control button { width: 100%; }
#sound-toggle-btn[aria-pressed="true"] { background: #354737; }
#sound-toggle-btn[aria-pressed="false"] { background: #573c3c; }
#quality-toggle-btn { background: #30445e; }
#settings-panel button:hover { filter: brightness(1.18); }
#settings-panel :focus-visible,
#structural-preview-button:focus-visible {
  outline: 3px solid #ffe4a1;
  outline-offset: -3px;
}
.settings-help { color: #ccc; margin-bottom: 16px; font-size: 14px; }
#preview-details { border-top: 1px solid #655235; padding-top: 8px; }
#preview-details summary { cursor: pointer; padding: 10px 0; min-height: 44px; color: #ead49d; }
#preview-details h3 { font-size: 16px; margin: 12px 0 6px; color: #ead49d; }
#preview-details p { margin-bottom: 10px; }
#preview-details ul { margin: 8px 0 12px; padding-left: 22px; }
#preview-details li { margin-bottom: 8px; }
#preview-details a { color: #b9d8ff; text-underline-offset: 3px; overflow-wrap: anywhere; }
.settings-footer {
  flex: 0 0 auto;
  padding: 12px 20px;
  border-top: 1px solid #655235;
}
#settings-panel #resume-btn { width: 100%; background: #8a632d; font-weight: bold; font-size: 17px; }
.settings-footer p { margin-top: 6px; text-align: center; font-size: 12px; color: #bbb; }
body.settings-open::before { display: none !important; }
@media (max-height: 480px) {
  .settings-header, .settings-footer { padding: 8px 14px; }
  #settings-content { padding: 10px 14px; }
  #settings-title { font-size: 21px; }
}
@media (max-width: 600px) and (orientation: portrait) {
  /* Above the joystick/jump controls and the inherited rotate-device hint. */
  #structural-preview-button { bottom: calc(240px + env(safe-area-inset-bottom, 0px)); }
}

/* The same entry reserves space inside the open map instead of covering its
   quick-travel buttons. Map canvas dimensions and coordinates are unchanged. */
#minimap #structural-preview-button {
  position: sticky;
  top: 0;
  left: auto;
  bottom: auto;
  transform: none;
  width: 100%;
  max-width: 100%;
  margin-bottom: 12px;
  z-index: 2;
  background: #211e18;
}
body.map-open #minimap {
  scroll-padding-top: 68px;
}

/* The map is a non-modal walking tool. Reserve real, uncovered control lanes. */
#minimap {
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: min(94vw, 780px);
  max-width: 94vw;
  max-height: 96vh;
  overscroll-behavior: contain;
}
#minimap #teleport-points { grid-template-columns: repeat(4, 1fr); }
#minimap button:focus-visible,
#minimap-preview:focus-visible { outline: 3px solid #ffe4a1; outline-offset: -3px; }
#minimap.minimap-touch {
  top: calc(8px + env(safe-area-inset-top, 0px));
  transform: translateX(-50%);
  width: min(400px, calc(100vw - 16px));
  max-height: calc(100dvh - 200px - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px));
}
#minimap.minimap-touch #teleport-points { grid-template-columns: repeat(2, 1fr); }
@media (orientation: landscape) and (min-width: 520px) {
  #minimap.minimap-touch {
    left: calc(164px + env(safe-area-inset-left, 0px));
    right: calc(164px + env(safe-area-inset-right, 0px));
    width: auto;
    max-width: 400px;
    margin-inline: auto;
    transform: none;
    max-height: calc(100dvh - 16px - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px));
  }
}

/* Open-map presentation only; the closed 118px mobile preview is independent. */
#minimap [hidden] { display: none !important; }
#minimap-presentation {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin-bottom: 8px;
}
#minimap-status { color: #ffe4a1; font-size: 13px; line-height: 18px; }
#minimap-heading { white-space: nowrap; }
#minimap-compact-hint { display: none; }
#minimap-size-toggle {
  min-width: 44px;
  min-height: 44px;
  padding: 4px 8px;
  color: #ffd764;
  background: #382d20;
  border: 1px solid #9f804a;
  border-radius: 6px;
  font: 13px/1.3 sans-serif;
  touch-action: manipulation;
  cursor: pointer;
}
#minimap[data-compact="true"] {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) 44px;
  gap: 6px;
  top: calc(8px + env(safe-area-inset-top, 0px));
  right: calc(8px + env(safe-area-inset-right, 0px));
  left: auto;
  transform: none;
  margin: 0;
  width: 240px;
  max-width: calc(100vw - 16px - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px));
  max-height: calc(100dvh - 16px - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px));
  padding: 6px !important;
  scroll-padding-top: 0;
}
#minimap.minimap-touch[data-compact="true"] {
  width: 220px;
  max-height: calc(100dvh - 200px - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px));
}
#minimap[data-compact="true"] #minimap-presentation { display: contents; }
#minimap[data-compact="true"] #minimap-status { grid-area: 1 / 1 / auto / -1; text-align: center; }
#minimap[data-compact="true"] #minimap-compact-hint { display: inline; margin-left: 8px; color: #d7c9ab; font-size: 11px; }
#minimap[data-compact="true"] > canvas { grid-area: 2 / 1 / auto / -1; min-width: 0; box-sizing: border-box; }
#minimap[data-compact="true"] #minimap-size-toggle { grid-area: 3 / 2; min-width: 44px; padding-inline: 2px; font-size: 12px; }
#minimap[data-compact="true"] #minimap-close { grid-area: 3 / 3; min-width: 44px; margin: 0 !important; padding: 2px; font-size: 12px; }
#minimap[data-compact="true"] #structural-preview-button {
  grid-area: 3 / 1;
  position: static;
  width: 100%;
  min-width: 44px;
  min-height: 44px;
  margin: 0;
  padding: 2px;
  font-size: 11px;
  line-height: 1.3;
}
#minimap[data-compact="true"] #structural-preview-button span { display: block; white-space: nowrap; font-size: 9px; }
#minimap[data-compact="true"][data-compact-collapsed="true"] {
  max-height: calc(100dvh - 16px - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px));
}
@media (orientation: landscape) and (min-width: 520px) {
  #minimap.minimap-touch[data-compact="true"] {
    right: calc(164px + env(safe-area-inset-right, 0px));
    max-width: calc(100vw - 328px - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px));
  }
  #minimap.minimap-touch[data-compact="true"][data-compact-collapsed="true"] {
    left: calc(164px + env(safe-area-inset-left, 0px));
    right: calc(164px + env(safe-area-inset-right, 0px));
    width: auto;
    max-width: 320px;
    margin-inline: auto;
  }
}

/* Place details replace only the map's content, within its existing safe box. */
#minimap #teleport-heading,
#minimap #place-list h2,
#minimap #bridge-facilities h2 { color: #ffe4a1; font-size: 16px; margin: 14px 0 8px; }
#minimap #place-list,
#minimap #bridge-facilities { display: flex; flex-wrap: wrap; gap: 6px; }
#minimap #place-list h2,
#minimap #bridge-facilities h2 { flex-basis: 100%; }
#minimap #place-search {
  flex-basis: 100%; width: 100%; min-width: 0; min-height: 44px;
  box-sizing: border-box; border: 1px solid #9f804a; border-radius: 6px;
  background: #211c17; color: #ffe4a1; padding: 8px 12px; font: inherit;
}
#minimap #place-search::placeholder { color: #d3c7b0; }
#minimap #place-search-count { flex-basis: 100%; margin: 2px 0; color: #d3c7b0; font-size: 14px; }
#minimap #place-directory,
#minimap #bridge-facility-directory {
  display: flex; flex-wrap: wrap; gap: 6px; width: 100%;
  max-height: min(240px, 36dvh); overflow-y: auto; overscroll-behavior: contain;
  touch-action: pan-y;
}
/* Keep the directory scroll offset when translated labels reflow. */
#minimap #place-directory { overflow-anchor: none; }
#minimap #place-directory button[hidden],
#minimap #bridge-facility-directory button[hidden] { display: none !important; }

#minimap #place-list button,
#minimap #bridge-facility-directory button,
#minimap #place-resume,
#minimap #place-header button,
#minimap #place-info button {
  min-width: 44px;
  min-height: 44px;
  padding: 8px 12px;
  border: 1px solid #9f804a;
  border-radius: 6px;
  background: #382d20;
  color: #ffe4a1;
  font-size: 14px;
  line-height: 1.45;
  overflow-wrap: anywhere;
  cursor: pointer;
  touch-action: manipulation;
}
#minimap #place-resume { margin-top: 10px; }
#minimap[data-detail="true"] {
  display: flex !important;
  flex-direction: column;
  height: min(640px, 96dvh);
  overflow: hidden !important;
}
#minimap.minimap-touch[data-detail="true"] {
  height: min(640px, calc(100dvh - 200px - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px)));
}
@media (orientation: landscape) and (min-width: 520px) {
  #minimap.minimap-touch[data-detail="true"] {
    height: min(640px, calc(100dvh - 16px - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px)));
  }
}
#minimap[data-detail="true"] #minimap-presentation,
#minimap[data-detail="true"] #structural-preview-button { flex-shrink: 0; }
#minimap #place-header { display: flex; gap: 8px; flex-shrink: 0; margin-bottom: 8px; }
#minimap #place-header button { flex: 1; margin: 0 !important; }
#minimap #place-info {
  min-width: 0;
  min-height: 0;
  overflow-y: auto;
  overflow-wrap: anywhere;
  overscroll-behavior: contain;
  touch-action: pan-y;
  color: #f1e8d5;
  font-size: 16px;
  line-height: 1.65;
  padding: 0 8px 12px 0;
}
/* Keep the unique travel action visible while the complete card text scrolls. */
#minimap #place-actions {
  position: sticky;
  top: 0;
  z-index: 1;
  display: flex;
  flex-wrap: wrap;
  padding: 4px 0 8px;
  background: #171b18;
}
#minimap #place-actions button { margin: 0; }
#minimap #place-info h2 { margin: 2px 0 0; font-size: 24px; color: #ffe4a1; }
#minimap #place-info h3 { margin: 20px 0 8px; font-size: 17px; color: #ffe4a1; }
#minimap #place-info p { margin: 8px 0; }
#minimap #place-info .place-tag { color: #d9bc7d; font-size: 14px; }
#minimap #place-info .place-note { color: #d3c7b0; font-size: 14px; }
#minimap #place-info ul { padding-left: 22px; }
#minimap #place-info li { margin-bottom: 10px; }
#minimap #place-info a { display: inline-block; min-height: 44px; padding-block: 6px; box-sizing: border-box; color: #ffe4a1; }
#minimap #place-info a:focus-visible,
#minimap #place-info h2:focus-visible { outline: 3px solid #ffe4a1; outline-offset: -3px; }
#minimap #place-announcement { position: absolute; width: 1px; height: 1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
@media (max-height: 340px) {
  #minimap[data-detail="true"] { padding: 8px !important; }
  #minimap[data-detail="true"] #minimap-presentation { margin-bottom: 4px; }
  #minimap[data-detail="true"] #structural-preview-button { margin-bottom: 4px; min-height: 44px; }
}

/* Keep the persistent location label clear of closed and compact maps. */
body:has(#minimap.minimap-touch) #location-panel {
  top: calc(20px + env(safe-area-inset-top, 0px)) !important;
  left: calc(20px + env(safe-area-inset-left, 0px)) !important;
  padding: 8px 12px !important;
  font-size: 14px !important;
  overflow-wrap: anywhere;
}
body:not(.map-open):has(#minimap-preview) #location-panel {
  /* 20px left + 12px gap + 118px preview + 16px right. */
  max-width: calc(100vw - 166px - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px));
}
body:has(#minimap[data-compact="true"]) #location-panel {
  /* Desktop card: 240px wide, with its 8px right margin. */
  max-width: calc(100vw - 280px - env(safe-area-inset-right, 0px));
  overflow-wrap: anywhere;
}
body:has(#minimap.minimap-touch[data-compact="true"]) #location-panel {
  max-width: calc(100vw - 260px - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px));
}
@media (orientation: landscape) and (min-width: 520px) {
  body:has(#minimap.minimap-touch[data-compact="true"]) #location-panel {
    /* The card reserves a 164px right control lane and shrinks if needed. */
    max-width: max(132px, calc(100vw - 416px - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px)));
  }
  body:has(#minimap.minimap-touch[data-compact="true"][data-compact-collapsed="true"]) #location-panel {
    /* Short strip is centered, capped at 320px, between the two 164px lanes. */
    max-width: max(132px, calc((100vw - 384px - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px)) / 2));
  }
}
@media (max-width: 360px) {
  body:has(#minimap[data-compact="true"]) #location-panel {
    /* 8px top + maximum 236px card + 12px gap; keep long labels readable. */
    top: calc(256px + env(safe-area-inset-top, 0px)) !important;
    max-width: calc(100vw - 40px - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px)) !important;
  }
  body:has(#minimap[data-compact="true"][data-compact-collapsed="true"]) #location-panel {
    /* Without the canvas the compact strip is at most 92px high. */
    top: calc(112px + env(safe-area-inset-top, 0px)) !important;
  }
}

/* R79 readable project entry; links retain the existing anchor input exclusion. */
.welcome-content { max-height: calc(100dvh - 40px); overflow-y: auto; }
.welcome-content .project-summary { font-size: 14px; line-height: 1.55; margin: 10px 0; }
.project-discovery { display: flex; flex-wrap: wrap; justify-content: center; gap: 12px; margin: 14px 0; }
.project-discovery a { color: #f1d58d; text-decoration: underline; padding: 5px; }
.project-discovery a:focus-visible { outline: 2px solid #fff; outline-offset: 3px; }
.no-script-project { position: fixed; inset: 0; z-index: 10001; overflow: auto; padding: 2rem; background: #171b23; color: #fff; }
.no-script-project a { color: #f1d58d; }

/* Bilingual presentation controls. These never own world or map input. */
.language-control { display: flex; align-items: center; justify-content: center; gap: 8px; max-width: 100%; color: #fff2ce; font: 13px/1.4 system-ui, sans-serif; }
.language-control select { min-height: 44px; min-width: 112px; max-width: 100%; padding: 7px 10px; color: #fff2ce; background: #241f18; border: 1px solid #bfa36c; border-radius: 7px; font: inherit; }
.language-control select:focus-visible { outline: 3px solid #fff2ce; outline-offset: 2px; }
#tour-language-control { position: fixed; left: 50%; bottom: calc(64px + env(safe-area-inset-bottom, 0px)); transform: translateX(-50%); z-index: 9200; width: max-content; max-width: calc(100vw - 24px); padding: 2px 8px; border-radius: 8px; background: #161512ed; }
#settings-language-control { justify-content: space-between; margin: 14px 0; padding: 8px 0; border-top: 1px solid #655235; }
body.settings-open #tour-language-control, body.map-open #tour-language-control { visibility: hidden; }
@media (max-width: 600px) and (orientation: portrait) { #tour-language-control { bottom: calc(300px + env(safe-area-inset-bottom, 0px)); } }

/* Supplemental descriptions share search and card state, never add travel targets. */
#minimap #supplemental-place-list { display:flex;flex-wrap:wrap;gap:6px; }
#minimap #supplemental-place-list h2 { flex-basis:100%;color:#ffe4a1;font-size:16px;margin:14px 0 8px; }
#minimap #supplemental-place-directory { display:flex;flex-wrap:wrap;gap:6px;width:100%;max-height:min(240px,36dvh);overflow-y:auto;overscroll-behavior:contain;touch-action:pan-y; }
#minimap #supplemental-place-directory button { min-width:44px;min-height:44px;padding:8px 12px;border:1px solid #9f804a;border-radius:6px;background:#382d20;color:#ffe4a1;font-size:14px;line-height:1.45;overflow-wrap:anywhere;cursor:pointer;touch-action:manipulation; }
#minimap #supplemental-place-directory button[hidden] { display:none!important; }

#minimap-presentation { flex-wrap:wrap; }
#map-language-control { flex-basis:100%;width:100%; }
#minimap[data-compact="true"] #map-language-control { grid-area:4 / 1 / auto / -1; }
@media (max-width: 768px) and (orientation: portrait) {
  html[lang="en"] body::before {
    content: "For a better experience, rotate your device";
    white-space: normal; width: max-content; max-width: calc(100vw - 24px); text-align: center;
  }
}
